/* 几种常见背景 */

/* 深色 (默认风格) */
ssp.sceneTool.setBackgroundColor('#0a0a1a');

/* 蓝天 (白天建筑可视化) */
ssp.sceneTool.setBackgroundColor('#87ceeb');

/* 黑色 (拍电影感) */
ssp.sceneTool.setBackgroundColor(0x000000);

/* 配合雾化看深度 */
ssp.sceneTool.setBackgroundColor('#0a0a1a');
ssp.sceneTool.setFog({ color: '#0a0a1a', near: 100, far: 500 });
